        } catch (error) {
            _satellite.logger.error("xdmBuilder eVars", error)
        }
    },
    props(xdmObject, propNumber, propValue = "") {
        try {
            if (propValue)
                this.getSet(xdmObject, `_experience.analytics.customDimensions.props.prop${String(propNumber)}`, String(propValue))
        } catch (error) {
            _satellite.logger.error("xdmBuilder props", error)
        }
    },
    events(xdmObject, eventNumber, eventValue = 1, eventSerialization = "") {
        try {
            let eventRange = "";
            if (eventNumber) {
                if (eventNumber >= 1 && eventNumber <= 100) {
                    eventRange = "event1to100";
                } else if (eventNumber >= 101 && eventNumber <= 200) {
                    eventRange = "event101to200";
                } else if (eventNumber >= 201 && eventNumber <= 300) {
                    eventRange = "event201to300";
                } else {
                    throw new Error("Events Error: Number is outside the specified ranges.");
                }
            } else {
                throw new Error("Events Error: No eventNumber found.");
            }

            let eventChildObj = {};
            if (eventSerialization)
                eventChildObj = {
                    "id": String(eventSerialization),
                    "value": Number(eventValue)
                };
            else
                eventChildObj = {
                    "value": Number(eventValue)
                };
            this.getSet(xdmObject, `_experience.analytics.${eventRange}.event${eventNumber}`, eventChildObj)
        } catch (error) {
            _satellite.logger.error("xdmBuilder event1to100", error)
        }
    },
    commerce(xdmObject, commerceEvent, eventValue = 1, eventSerialization = "") {
        try {
            const validCommerceEvents = [
                "checkouts",
                "order",
                "productListAdds",
                "productListOpens",
                "productListRemovals",
                "productListViews",
                "productViews",
                "purchases"
            ]

            if (!validCommerceEvents.includes(commerceEvent)) {
                throw new Error("Commerce Event is not valid.")
            }

            if (eventSerialization)
                eventChildObj = {
                    "id": String(eventSerialization),
                    "value": Number(eventValue)
                };
            else
                eventChildObj = {
                    "value": Number(eventValue)
                };
            this.getSet(xdmObject, `commerce.${String(commerceEvent)}`, eventChildObj)

        } catch (error) {
            _satellite.logger.error("xdmBuilder commerceEvent", error)
        }
    },
    commerceOrder(xdmObject, currencyCode = "", purchaseID = "", transactionID = "") {
        try {
            let orderObject = {
                ...(currencyCode) && { "currencyCode": currencyCode },
                ...(purchaseID) && { "purchaseID": purchaseID },
                ...(transactionID) && { "payments": [{ transactionID }] }
            };
            this.getSet(xdmObject, `commerce.order`, orderObject)
        } catch (error) {
            _satellite.logger.error("xdmBuilder commerceOrder", error)
        }
    },
    productListItems(xdmObject, productName, productCategory = "", priceTotal = "", qty = "", merchEvarEvents = {}) {
        try {
            if (!productName) {
                throw new Error("No product name was entered.")
            }

            var productItem = {
                ...(productName) && { "name": productName },
                ...(priceTotal) && { "priceTotal": priceTotal },
                ...(qty) && { "quantity": qty },
                ...(merchEvarEvents) && merchEvarEvents
            }
            if (productCategory) {
                productItem.productCategories = [{ "categoryID": productCategory }]
            }

            if (Array.isArray(xdmObject.productListItems)) {
                xdmObject.productListItems.push(productItem)
            } else {
                this.getSet(xdmObject, "productListItems", [productItem])
            }

        } catch (error) {
            _satellite.logger.error("xdmBuilder productListItems", error)
        }
    },
    lists1to3(xdmObject, listVal, listMainObj) {
        try {
            let validListNames = [1, 2, 3];
            let listObj = [];
            if (!validListNames.includes(Number(listVal))) { throw new Error("Invalid List Number") }

            if (Array.isArray(listMainObj) && listMainObj.length > 0) {
                for (var i = 0; i < listMainObj.length; i++) {
                    listObj[i] = {
                        "value": String(listMainObj[i])
                    };
                }
            }

            if (listObj) {
                this.getSet(xdmObject, `_experience.analytics.customDimensions.lists.list${String(listVal)}.list`, listObj)
            }
        } catch (error) {
            _satellite.logger.error("xdmBuilder lists1to3", error)
        }
    },
    listProps(xdmObject, listProp, delimiter, listMainObj) {
        try {
            if (Number(listProp) < 1 || Number(listProp) > 75) { throw new Error("Invalid List Prop Number") }
            if (!String(delimiter)) { throw new Error("Invalid List Prop Delimiter") }

            if (Array.isArray(listMainObj) && listMainObj.length > 0) {
                this.getSet(xdmObject, `_experience.analytics.customDimensions.listProps.prop${String(listProp)}.delimiter`, delimiter)
                this.getSet(xdmObject, `_experience.analytics.customDimensions.listProps.prop${String(listProp)}.values`, listMainObj)
            } else {
                throw new Error("Invalid List Prop listMainObj")
            }
        } catch (error) {
            _satellite.logger.error("xdmBuilder listsProps", error)
        }
    },
    marketTrackingCode(xdmObject, trackingCode) {
        try {
            if (typeof trackingCode === "string" && trackingCode.length > 0) {
                this.getSet(xdmObject, "marketing.trackingCode", trackingCode);
            }
        } catch (error) {
            _satellite.logger.error("xdmBuilder marketTrackingCode", error)
        }
    },
