                ...(pageName) && { "name": pageName },
                ...(url) && { "URL": url },
                ...(pageView) && { "pageViews": { "value": pageView } },
                ...(server) && { "server": server },
                ...(siteSection) && { "siteSection": siteSection },
                ...(typeof (isErrorPageFlag) === "boolean") && { "isErrorPage": (isErrorPageFlag) }
            };
            this.getSet(xdmObject, `web.webPageDetails`, webPageDetailsObject)
        } catch (error) {
            _satellite.logger.error("xdmBuilder webPageDetails", error)
        }
    },
    webInteraction(xdmObject, clickName, clickType, linkClickValue = 0, clickURL) {
        try {
            let validClickTypes = ["other", "download", "exit"];

