                throw new Error("Invalid Click Type");
            }

            let webInteractionObject = {
                ...(clickName) && { "name": clickName },
                ...(linkClickValue) && { "linkClicks": { "value": linkClickValue } },
                ...(clickType) && { "type": clickType },
                ...(clickURL) && { "URL": clickURL }
            };
            this.getSet(xdmObject, `web.webInteraction`, webInteractionObject)
        } catch (error) {
            _satellite.logger.error("xdmBuilder webInteraction", error)
        }

