                    alloy.xdmBuilder.getSet(xdmObject, "edgeConfigOverrides.com_adobe_target.propertyToken", String(propertyToken));
                } else {
                    throw new Error("Property Token is invalid.")
                }
            } catch (error) {
                _satellite.logger.error("Override Datastream", error);
            }
        },
        aepEventDataset: function (xdmObject, datasetID) {
            try {
                if (datasetID) {
                    alloy.xdmBuilder.getSet(xdmObject, "edgeConfigOverrides.com_adobe_experience_platform.datasets.event.datasetId", String(datasetID));
                } else {
                    throw new Error("Dataset ID is invalid.")
                }
            } catch (error) {
                _satellite.logger.error("Override Datastream", error);
            }
        }
