/* Adobe Consulting Plugin: kebabCase v1.1 */
alloy.helper.kebabCase = (string) => {
    if (typeof string !== "string") {
        _satellite.logger.error("Adobe Kebab Case Error - Parameter should be a string");
        return
    }

    return string
        .replace(/([a-z])([A-Z])/g, "$1-$2")
        .replace(/[\s_]+/g, '-')
        .toLowerCase();
};

/* Adobe Upper Case String v1.1 */
alloy.helper.convertToUpperCase = (input) => {
    if (typeof input === "object") {
      _satellite.logger.error("Cannot convert object into uppercase string");
      return
