                this.getSet(xdmObject, `data.__adobe.target`, targetParameters)
        } catch (error) {
            _satellite.logger.error("xdmBuilder targetParams", error)
        }
    },
    identityMap(xdmObject, identityNamespace, identityValue, authenticatedState, identityPrimary = false) {
        try {
