                xdmObject.identityMap[identityNamespace].push(identifier)
            } else {
                this.getSet(xdmObject, `identityMap.${String(identityNamespace)}`, [identifier])
            }
        } catch (error) {
            _satellite.logger.error("xdmBuilder identityMap", error)
        }
    },
